-- Insert Quiz Questions for Lesson: Understand the Document Journey

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 14 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 14 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'understand-document-journey' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson understand-document-journey not found in module 14';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main difference between a template and a document?', 
    '["A template is reusable; a document is a copy prepared for a particular contact or deal.","A template is sent directly; a document is only a draft.","A template is for payments; a document is for signatures.","There is no difference between a template and a document."]'::jsonb,
    'A template is reusable; a document is a copy prepared for a particular contact or deal.',
    'A template holds reusable wording and fields, while a document is created for a specific contact or deal from that template.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does ''Waiting for Others'' usually mean?', 
    '["The document has been completed successfully.","The document is still in draft mode.","One or more signers still need to complete an assigned action.","The document has been deleted."]'::jsonb,
    'One or more signers still need to complete an assigned action.',
    '''Waiting for Others'' means one or more signers still need to complete their assigned fields or actions on the document.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should happen immediately after a document is completed?', 
    '["Delete the document from the system.","The business should complete its planned next step, such as onboarding, payment, or scheduling.","Wait for the client to request the next step.","Create a new template from the completed document."]'::jsonb,
    'The business should complete its planned next step, such as onboarding, payment, or scheduling.',
    'After completion, the business should immediately begin its planned next step, such as onboarding, payment collection, or scheduling.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


