-- Insert Quiz Questions for Lesson: Add a Simple Workflow

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 14 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 14 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'add-simple-workflow' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson add-simple-workflow not found in module 14';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Name two possible workflow triggers for a document.', 
    '["A tag being added or an opportunity stage changing","The user logging in or logging out","A calendar event starting or ending","A payment being received or refunded"]'::jsonb,
    'A tag being added or an opportunity stage changing',
    'Common triggers include a tag being added to a contact or an opportunity stage changing, such as moving to ''Proposal Approved''.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why might a workflow create a draft instead of sending directly?', 
    '["To let a person check client details and terms before the document goes out","To save storage space in LeadProspectrr","To prevent the document from being signed","To automatically delete the document after review"]'::jsonb,
    'To let a person check client details and terms before the document goes out',
    'Creating a draft allows a team member to review client details and terms before the document is actually sent to the client.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What contact detail is required before a document can be sent correctly through the workflow?', 
    '["A valid email address","A phone number","A mailing address","A social media profile"]'::jsonb,
    'A valid email address',
    'A valid email address is required for the contact to receive the secure link and complete the document.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
